css:
.ds-hero { color: rgb(255, 255, 255); background-image: linear-gradient(rgb(43, 123, 214) 0%, rgb(87, 163, 232) 40%, rgb(168, 213, 240) 76%, rgb(238, 248, 242) 100%); padding: 0px 0px 64px; font-family: "Inter Tight", sans-serif; position: relative; overflow: hidden; }
.ds-cloud { filter: blur(18px); pointer-events: none; background-image: radial-gradient(closest-side, rgba(255, 255, 255, 0.95), rgba(255, 255, 255, 0.55) 45%, rgba(255, 255, 255, 0) 100%); border-radius: 50%; position: absolute; }
.ds-cloud-a { width: 900px; height: 260px; bottom: 120px; left: -200px; }
.ds-cloud-b { width: 1100px; height: 300px; bottom: 40px; right: -300px; }
.ds-cloud-c { width: 700px; height: 180px; bottom: -60px; left: 30%; }
.ds-nav { z-index: 5; justify-content: space-between; align-items: center; max-width: 1240px; margin-left: auto; margin-right: auto; padding: 22px 32px; display: flex; position: relative; }
.ds-logo { color: rgb(255, 255, 255); align-items: center; text-decoration: none; display: flex; }
.ds-logo-mark { color: rgb(14, 21, 17); letter-spacing: -0.02em; background-color: rgb(241, 242, 241); background-image: url("https://cdn.prod.website-files.com/6788b68d1a634575bfb48323/6b095909892062dc1cf6a2c2_dualsync-logo.png"); background-position: 47% 51%; background-size: 170% auto; border-radius: 10px; justify-content: center; align-items: center; width: 36px; height: 36px; margin-right: 10px; font-size: 0px; font-weight: 700; display: flex; box-shadow: rgba(14, 21, 17, 0.35) 0px 6px 16px -6px; }
.ds-logo-word { letter-spacing: -0.03em; font-size: 19px; font-weight: 600; }
.ds-nav-links { display: flex; }
.ds-nav-link { opacity: 0.9; color: rgb(255, 255, 255); letter-spacing: 0.12em; text-transform: uppercase; margin-left: 18px; margin-right: 18px; font-family: "JetBrains Mono", monospace; font-size: 11px; text-decoration: none; }
.ds-nav-link:hover { opacity: 1; }
.ds-btn-green { z-index: 2; color: rgb(255, 255, 255); letter-spacing: 0.1em; text-transform: uppercase; background-color: rgb(14, 21, 17); border-radius: 999px; align-items: center; height: 46px; padding-left: 22px; padding-right: 22px; font-family: "JetBrains Mono", monospace; font-size: 12px; font-weight: 600; text-decoration: none; transition: transform 0.25s, background-color 0.2s; display: inline-flex; position: relative; box-shadow: rgba(14, 21, 17, 0.55) 0px 10px 24px -10px; }
.ds-btn-green:hover { color: rgb(56, 224, 123); background-color: rgb(22, 66, 43); transform: translateY(-2px); }
.ds-btn-sm { height: 40px; padding-left: 18px; padding-right: 18px; font-size: 11px; }
.ds-btn-glass { backdrop-filter: blur(10px); color: rgb(255, 255, 255); letter-spacing: 0.1em; text-transform: uppercase; background-color: rgba(14, 21, 17, 0.28); border: 1px solid rgba(255, 255, 255, 0.3); border-radius: 999px; align-items: center; height: 46px; margin-right: 12px; padding-left: 22px; padding-right: 22px; font-family: "JetBrains Mono", monospace; font-size: 12px; font-weight: 600; text-decoration: none; transition: transform 0.25s; display: inline-flex; }
.ds-btn-glass:hover { transform: translateY(-2px); }
.ds-hero-inner { z-index: 4; text-align: center; max-width: 920px; margin-left: auto; margin-right: auto; padding: 72px 24px 0px; position: relative; }
.ds-badge { backdrop-filter: blur(8px); letter-spacing: 0.12em; text-transform: uppercase; background-color: rgba(255, 255, 255, 0.16); border: 1px solid rgba(255, 255, 255, 0.3); border-radius: 999px; align-items: center; padding: 8px 14px; font-family: "JetBrains Mono", monospace; font-size: 11px; display: inline-flex; }
.ds-dot { background-color: rgb(56, 224, 123); border-radius: 50%; width: 7px; height: 7px; margin-right: 10px; box-shadow: rgba(56, 224, 123, 0.35) 0px 0px 0px 3px; }
.ds-hero-title { color: rgb(255, 255, 255); letter-spacing: -0.045em; margin-top: 28px; margin-bottom: 0px; font-size: 84px; font-weight: 500; line-height: 1; }
.ds-hero-soft { color: rgba(255, 255, 255, 0.7); }
.ds-hero-sub { color: rgba(255, 255, 255, 0.92); max-width: 560px; margin: 22px auto 0px; font-size: 18px; line-height: 28px; }
.ds-hero-ctas { justify-content: center; margin-top: 32px; display: flex; }
.ds-arc { z-index: 3; perspective: 1300px; justify-content: center; align-items: flex-start; height: 250px; margin-top: 72px; display: flex; position: relative; }
.ds-card { color: rgb(14, 21, 17); width: 170px; height: 210px; transform-style: preserve-3d; background-color: rgb(255, 255, 255); border-radius: 18px; flex: 0 0 auto; margin-left: -10px; margin-right: -10px; padding: 14px; transition: transform 0.5s cubic-bezier(0.2, 0.8, 0.2, 1); position: relative; overflow: hidden; box-shadow: rgba(16, 40, 80, 0.45) 0px 30px 60px -20px; }
.ds-card:hover { z-index: 10; transform: translateY(-10px) rotateY(0deg) scale(1.04); }
.ds-c1 { transform-style: preserve-3d; transform: rotateY(34deg) translateZ(-90px) translateY(26px); }
.ds-c2 { transform-style: preserve-3d; transform: rotateY(22deg) translateZ(-40px) translateY(10px); }
.ds-c3 { transform-style: preserve-3d; transform: rotateY(11deg) translateZ(-10px); }
.ds-c4 { z-index: 4; transform-style: preserve-3d; transform: translateZ(0px) translateY(-6px); }
.ds-c5 { transform-style: preserve-3d; transform: rotateY(-11deg) translateZ(-10px); }
.ds-c6 { transform-style: preserve-3d; transform: rotateY(-22deg) translateZ(-40px) translateY(10px); }
.ds-c7 { transform-style: preserve-3d; transform: rotateY(-34deg) translateZ(-90px) translateY(26px); }
.ds-card-dark { color: rgb(255, 255, 255); background-color: rgb(14, 21, 17); }
.ds-card-green { background-color: rgb(227, 248, 235); }
.ds-card-photo-a { background-image: linear-gradient(rgba(0, 0, 0, 0) 55%, rgba(0, 0, 0, 0.35)), url("https://cdn.prod.website-files.com/6788b68d1a634575bfb48323/6b09590986837e24760917a1_haseeb.jpeg"); background-position: 50% 20%; background-size: cover; }
.ds-card-photo-b { background-image: linear-gradient(rgba(0, 0, 0, 0) 55%, rgba(0, 0, 0, 0.35)), url("https://cdn.prod.website-files.com/6788b68d1a634575bfb48323/6b0959095e765aead052b9e5_siddique.jpeg"); background-position: 50% 20%; background-size: cover; }
.ds-photo-tag { color: rgb(14, 21, 17); background-color: rgba(255, 255, 255, 0.94); border-radius: 10px; padding: 8px 10px; font-size: 11px; font-weight: 600; position: absolute; bottom: 10px; left: 10px; right: 10px; }
.ds-card-label { color: rgb(91, 98, 94); font-size: 11px; line-height: 14px; }
.ds-on-dark { color: rgb(154, 166, 160); }
.ds-ink { color: rgb(14, 21, 17); }
.ds-white { color: rgb(255, 255, 255); }
.ds-card-big { letter-spacing: -0.03em; margin-top: 6px; font-size: 20px; font-weight: 600; }
.ds-card-huge { letter-spacing: -0.05em; margin-top: 16px; font-size: 56px; font-weight: 500; line-height: 1; }
.ds-card-text { margin-top: 10px; font-size: 12px; line-height: 16px; }
.ds-card-quote { letter-spacing: -0.02em; margin-top: 14px; font-size: 18px; font-weight: 500; line-height: 23px; }
.ds-bars { align-items: flex-end; height: 90px; margin-top: 22px; display: flex; }
.ds-bar { background-color: rgb(230, 235, 232); border-radius: 4px; flex: 1 1 0%; margin-right: 6px; }
.ds-b1 { height: 45%; }
.ds-b2 { height: 62%; }
.ds-b3 { height: 38%; }
.ds-b4 { height: 74%; }
.ds-b5 { height: 100%; }
.ds-bar-on { background-color: rgb(31, 184, 96); }
.ds-wave { align-items: center; height: 80px; margin-top: 18px; display: flex; }
.ds-w { background-color: rgb(56, 224, 123); border-radius: 2px; flex: 1 1 0%; margin-right: 4px; }
.ds-w1 { height: 25%; }
.ds-w2 { height: 60%; }
.ds-w3 { height: 90%; }
.ds-w4 { height: 45%; }
.ds-w5 { height: 100%; }
.ds-w6 { height: 55%; }
.ds-w7 { height: 30%; }
.ds-trust { z-index: 4; color: rgb(14, 21, 17); text-align: center; margin: 28px 0px 0px; font-size: 14px; position: relative; }
.ds-stars { color: rgb(14, 21, 17); letter-spacing: 2px; margin-right: 6px; }
.ds-strip { background-color: rgb(255, 255, 255); border-bottom: 1px solid rgb(230, 232, 230); padding: 30px 0px; overflow: hidden; }
.ds-strip-track { flex-wrap: wrap; justify-content: center; max-width: 1240px; margin-left: auto; margin-right: auto; display: flex; }
.ds-logo-txt { color: rgb(154, 160, 156); letter-spacing: -0.02em; white-space: nowrap; margin: 6px 30px; font-family: "Inter Tight", sans-serif; font-size: 20px; font-weight: 600; }
.ds-about { color: rgb(14, 21, 17); text-align: center; background-color: rgb(255, 255, 255); padding: 128px 24px 24px; font-family: "Inter Tight", sans-serif; }
.ds-eyebrow { color: rgb(91, 98, 94); letter-spacing: 0.12em; text-transform: uppercase; font-family: "JetBrains Mono", monospace; font-size: 11px; }
.ds-statement { letter-spacing: -0.04em; max-width: 880px; margin: 22px auto 0px; font-size: 50px; font-weight: 500; line-height: 1.12; }
.ds-statement-soft { color: rgb(167, 173, 169); }
.ds-bento-wrap { color: rgb(14, 21, 17); background-color: rgb(255, 255, 255); padding: 64px 32px 0px; font-family: "Inter Tight", sans-serif; }
.ds-bento { gap: 16px; grid-template-rows: auto; grid-template-columns: repeat(12, minmax(0px, 1fr)); grid-auto-rows: 250px; max-width: 1176px; margin-left: auto; margin-right: auto; display: grid; }
.ds-tile { border-radius: 24px; flex-direction: column; grid-column-start: span 4; padding: 24px; transition: transform 0.4s cubic-bezier(0.2, 0.8, 0.2, 1); display: flex; position: relative; overflow: hidden; }
.ds-tile:hover { transform: translateY(-4px); }
.ds-tile-photo { background-image: url("https://cdn.prod.website-files.com/6788b68d1a634575bfb48323/6b095909582518ff7791dd4e_founders-together.jpeg"); background-position: 50% 25%; background-size: cover; grid-row-start: span 2; }
.ds-tile-float { background-color: rgb(255, 255, 255); border-radius: 16px; padding: 18px; position: absolute; bottom: 16px; left: 16px; right: 16px; }
.ds-tile-grey { background-color: rgb(243, 244, 243); }
.ds-tile-green { color: rgb(14, 21, 17); background-color: rgb(227, 248, 235); }
.ds-tile-dark { color: rgb(255, 255, 255); background-color: rgb(14, 21, 17); }
.ds-tile-wide { grid-column-start: span 5; }
.ds-tile-narrow { grid-column-start: span 3; }
.ds-tile-num { letter-spacing: -0.045em; margin-top: 8px; font-size: 48px; font-weight: 500; line-height: 1; }
.ds-tile-xl { font-size: 72px; }
.ds-tile-small { color: rgb(91, 98, 94); font-size: 13px; line-height: 18px; }
.ds-tile-foot { color: rgb(91, 98, 94); max-width: 320px; margin-top: auto; font-size: 14px; line-height: 20px; }
.ds-tile-quote { letter-spacing: -0.015em; margin: 14px 0px 0px; font-size: 21px; line-height: 29px; }
.ds-sec { color: rgb(14, 21, 17); background-color: rgb(255, 255, 255); padding: 140px 32px 0px; font-family: "Inter Tight", sans-serif; }
.ds-sec-head { flex-wrap: wrap; justify-content: space-between; align-items: flex-end; max-width: 1176px; margin: 0px auto 40px; display: flex; }
.ds-h2 { letter-spacing: -0.04em; margin: 16px 0px 0px; font-size: 50px; font-weight: 500; line-height: 1.05; }
.ds-svc-list { border-bottom: 1px solid rgb(230, 232, 230); max-width: 1176px; margin-left: auto; margin-right: auto; }
.ds-svc { column-gap: 24px; color: rgb(14, 21, 17); border-top: 1px solid rgb(230, 232, 230); grid-template-rows: auto; grid-template-columns: 64px minmax(0px, 1fr) minmax(0px, 1.2fr) 48px; align-items: center; padding: 28px 0px; text-decoration: none; transition: padding-left 0.35s cubic-bezier(0.2, 0.8, 0.2, 1), background-color 0.3s; display: grid; }
.ds-svc:hover { background-color: rgb(246, 251, 248); padding-left: 16px; }
.ds-svc-n { color: rgb(91, 98, 94); letter-spacing: 0.1em; font-family: "JetBrains Mono", monospace; font-size: 12px; }
.ds-svc-name { letter-spacing: -0.035em; font-size: 30px; font-weight: 500; }
.ds-svc-desc { color: rgb(91, 98, 94); font-size: 16px; line-height: 24px; }
.ds-svc-arrow { color: rgb(56, 224, 123); background-color: rgb(14, 21, 17); border-radius: 50%; justify-content: center; align-items: center; width: 44px; height: 44px; font-size: 18px; display: flex; }
.ds-work { column-gap: 16px; grid-template-rows: auto; grid-template-columns: minmax(0px, 1.4fr) minmax(0px, 1fr); max-width: 1176px; margin-left: auto; margin-right: auto; display: grid; }
.ds-work-main { color: rgb(255, 255, 255); background-image: linear-gradient(160deg, rgb(22, 66, 43) 0%, rgb(14, 21, 17) 70%); border-radius: 24px; min-height: 500px; padding: 32px; text-decoration: none; display: block; position: relative; overflow: hidden; }
.ds-work-main:hover { color: rgb(255, 255, 255); }
.ds-work-title { letter-spacing: -0.035em; max-width: 440px; margin-top: 14px; font-size: 34px; font-weight: 500; line-height: 1.1; }
.ds-mock { color: rgb(14, 21, 17); background-color: rgb(255, 255, 255); border-radius: 14px; height: 250px; padding: 18px; transition: transform 0.6s cubic-bezier(0.2, 0.8, 0.2, 1); position: absolute; bottom: -30px; left: 32px; right: -40px; box-shadow: rgba(0, 0, 0, 0.4) 0px 30px 60px; }
.ds-mock-row { display: flex; }
.ds-kpi { background-color: rgb(243, 244, 243); border-radius: 10px; flex: 1 1 0%; margin-right: 10px; padding: 12px; }
.ds-kpi-g { background-color: rgb(227, 248, 235); }
.ds-chart { background-image: linear-gradient(rgba(56, 224, 123, 0.25), rgba(56, 224, 123, 0)); border-top: 2px solid rgb(31, 184, 96); border-radius: 10px; height: 120px; margin-top: 14px; }
.ds-work-side { row-gap: 16px; grid-template-rows: 1fr 1fr; grid-template-columns: 1fr; display: grid; }
.ds-work-card { color: rgb(14, 21, 17); background-color: rgb(243, 244, 243); border-radius: 24px; padding: 28px; text-decoration: none; transition: transform 0.4s cubic-bezier(0.2, 0.8, 0.2, 1); display: block; }
.ds-work-card:hover { transform: translateY(-4px); }
.ds-work-card-g { background-color: rgb(227, 248, 235); }
.ds-work-name { letter-spacing: -0.035em; margin-top: 12px; font-size: 30px; font-weight: 500; }
.ds-work-p { color: rgb(91, 98, 94); margin: 8px 0px 0px; font-size: 15px; line-height: 22px; }
.ds-cta-wrap { background-color: rgb(255, 255, 255); padding: 140px 32px 24px; font-family: "Inter Tight", sans-serif; }
.ds-cta { color: rgb(255, 255, 255); text-align: center; background-image: linear-gradient(rgb(47, 127, 224) 0%, rgb(74, 147, 234) 55%, rgb(125, 184, 242) 100%); border-radius: 28px; max-width: 1176px; margin-left: auto; margin-right: auto; padding: 104px 32px; position: relative; overflow: hidden; }
.ds-cta-title { z-index: 2; letter-spacing: -0.045em; max-width: 760px; margin: 0px auto; font-size: 64px; font-weight: 500; line-height: 1.02; position: relative; }
.ds-cta-sub { z-index: 2; color: rgba(255, 255, 255, 0.92); max-width: 460px; margin: 18px auto 30px; font-size: 17px; line-height: 26px; position: relative; }
.ds-foot { color: rgb(91, 98, 94); flex-wrap: wrap; justify-content: space-between; max-width: 1176px; margin: 32px auto 0px; font-size: 14px; display: flex; }
.ds-foot-strong { color: rgb(14, 21, 17); font-weight: 600; }
.ds-foot-link { color: rgb(91, 98, 94); }
.ds-steps { column-gap: 16px; grid-template-rows: auto; grid-template-columns: repeat(4, minmax(0px, 1fr)); max-width: 1176px; margin-left: auto; margin-right: auto; display: grid; }
.ds-step { background-color: rgb(243, 244, 243); border-radius: 24px; flex-direction: column; min-height: 300px; padding: 26px; transition: transform 0.4s cubic-bezier(0.2, 0.8, 0.2, 1), background-color 0.3s; display: flex; }
.ds-step:hover { background-color: rgb(227, 248, 235); transform: translateY(-6px); }
.ds-step-on { color: rgb(255, 255, 255); background-color: rgb(14, 21, 17); }
.ds-step-n { opacity: 0.65; letter-spacing: 0.12em; text-transform: uppercase; color: inherit; font-family: "JetBrains Mono", monospace; font-size: 11px; }
.ds-step-name { letter-spacing: -0.035em; margin-top: 18px; font-size: 30px; font-weight: 500; }
.ds-step-p { opacity: 0.75; color: inherit; margin: 10px 0px 0px; font-size: 15px; line-height: 22px; }
.ds-step-get { border-top: 1px solid rgba(127, 140, 133, 0.3); margin-top: auto; padding-top: 16px; font-size: 14px; line-height: 20px; }
.sx-nav { z-index: 10; justify-content: space-between; align-items: center; max-width: 1280px; margin-left: auto; margin-right: auto; padding: 24px 40px; display: flex; position: relative; }
.sx-brand { color: rgb(244, 247, 242); align-items: center; text-decoration: none; display: flex; }
.sx-mark { background-color: rgb(241, 242, 241); background-image: url("https://cdn.prod.website-files.com/6788b68d1a634575bfb48323/6b095909892062dc1cf6a2c2_dualsync-logo.png"); background-position: 47% 51%; background-size: 170% auto; border-radius: 10px; width: 36px; height: 36px; margin-right: 12px; display: block; position: relative; box-shadow: rgba(14, 21, 17, 0.35) 0px 6px 16px -6px; }
.sx-mark-a { border: 2px solid rgb(244, 247, 242); border-radius: 50%; width: 18px; height: 18px; display: none; position: absolute; top: 1px; left: 0px; }
.sx-mark-b { border: 2px solid rgb(56, 224, 123); border-radius: 50%; width: 18px; height: 18px; display: none; position: absolute; top: 1px; left: 12px; }
.sx-brand-word { letter-spacing: -0.035em; font-size: 20px; font-weight: 600; }
.sx-links { backdrop-filter: blur(10px); background-color: rgba(14, 21, 17, 0.22); border: 1px solid rgba(255, 255, 255, 0.3); border-radius: 999px; padding: 6px; display: flex; }
.sx-link { color: rgb(255, 255, 255); border-radius: 999px; padding: 8px 16px; font-size: 14px; font-weight: 500; text-decoration: none; transition: background-color 0.25s, color 0.25s; }
.sx-link:hover { color: rgb(244, 247, 242); background-color: rgba(244, 247, 242, 0.1); }
.sx-cta { color: rgb(255, 255, 255); background-color: rgb(14, 21, 17); border-radius: 999px; align-items: center; height: 42px; padding-left: 20px; padding-right: 20px; font-size: 14px; font-weight: 600; text-decoration: none; transition: background-color 0.25s, transform 0.25s; display: inline-flex; }
.sx-cta:hover { color: rgb(56, 224, 123); background-color: rgb(22, 66, 43); transform: translateY(-2px); }
.sx-pulse { background-color: rgb(56, 224, 123); border-radius: 50%; width: 8px; height: 8px; margin-right: 10px; display: inline-block; box-shadow: rgba(56, 224, 123, 0.22) 0px 0px 0px 4px; }
.sx-green { color: rgba(255, 255, 255, 0.7); }
.sx-paper { color: rgb(8, 20, 13); background-color: rgb(244, 247, 242); padding: 140px 0px 120px; font-family: "Inter Tight", sans-serif; }
.sx-wrap { max-width: 1280px; margin-left: auto; margin-right: auto; padding-left: 40px; padding-right: 40px; }
.sx-split { column-gap: 40px; grid-template-rows: auto; grid-template-columns: 220px minmax(0px, 1fr); display: grid; }
.sx-label { color: rgb(77, 92, 83); letter-spacing: 0.08em; text-transform: uppercase; padding-top: 12px; font-family: "JetBrains Mono", sans-serif; font-size: 12px; }
.sx-label.sx-label-ink { color: rgba(255, 255, 255, 0.85); }
.sx-statement { letter-spacing: -0.035em; margin: 0px; font-size: 48px; font-weight: 500; line-height: 1.12; }
.sx-numbers { border-top: 1px solid rgb(207, 221, 211); grid-template-rows: auto; grid-template-columns: repeat(4, minmax(0px, 1fr)); margin-top: 120px; display: grid; }
.sx-num { padding: 32px 24px 0px 0px; }
.sx-num-mask { overflow: hidden; }
.sx-num-v { color: rgb(8, 20, 13); letter-spacing: -0.06em; font-size: 120px; font-weight: 500; line-height: 1; }
.sx-num-u { color: rgb(13, 122, 63); letter-spacing: -0.03em; margin-left: 6px; font-size: 32px; }
.sx-num-l { color: rgb(77, 92, 83); max-width: 220px; margin-top: 16px; font-size: 15px; line-height: 22px; }
.sx-h2 { letter-spacing: -0.05em; margin: 14px 0px 0px; font-size: 72px; font-weight: 500; line-height: 1; }
.sx-kpis { column-gap: 10px; grid-template-rows: auto; grid-template-columns: repeat(3, minmax(0px, 1fr)); display: grid; }
.sx-kpi-l { opacity: 0.7; font-size: 12px; }
.sx-kpi-v { margin-top: 6px; font-size: 24px; font-weight: 600; }
.sx-bar-g { background-color: rgb(56, 224, 123); }
.sx-h40 { height: 40%; }
.sx-h48 { height: 48%; }
.sx-h55 { height: 55%; }
.sx-h62 { height: 62%; }
.sx-h70 { height: 70%; }
.sx-h75 { height: 75%; }
.sx-h85 { height: 85%; }
.sx-dark { color: rgb(244, 247, 242); background-color: rgb(8, 20, 13); padding: 140px 0px; font-family: "Inter Tight", sans-serif; }
.sx-label-d { color: rgb(157, 179, 165); }
.sx-feature { column-gap: 48px; color: rgb(244, 247, 242); background-color: rgb(14, 36, 24); border: 1px solid rgba(56, 224, 123, 0.18); border-radius: 32px; grid-template-rows: auto; grid-template-columns: minmax(0px, 5fr) minmax(0px, 7fr); align-items: center; padding: 48px; text-decoration: none; transition: border-color 0.4s; display: grid; }
.sx-feature:hover { color: rgb(244, 247, 242); border-color: rgba(56, 224, 123, 0.6); }
.sx-feature-title { letter-spacing: -0.04em; margin: 20px 0px 0px; font-size: 40px; font-weight: 500; line-height: 1.08; }
.sx-feature-meta { border-top: 1px solid rgba(244, 247, 242, 0.12); margin-top: 36px; padding-top: 24px; display: flex; }
.sx-fm { margin-right: 36px; }
